public static long sumOfDigs(long n) {
  long sum=0;
  String str=Long.toString(n);
  for(int i=0;i<str.length();i++)
   sum+=Long.parseLong(
        str.substring(i, i+1));
  return sum;
}

public static long sumOfDigs(long n) {
  long sum=0;
  do {
    sum+=n%10;
    n=n/10;
  }while(n>0);
  return sum;
}

public static long sumOfDigs(long n) {
  long sum=0;
  while(n>0) {
    n%=10;
    sum+=n;
    n/=10;
    }
  return sum;
}

